class Menu
{
    public static void main(String args[])
    {
        Scanner sc = new Scanner(System.in);
        System.out.println("1. Buzz number");
        System.out.println("2. GCD of two numbers");
        System.out.print("Enter your choice: ");
        int ch = sc.nextInt();
        switch (ch)
        {
            case 1:
                System.out.print("Enter a number: ");
                int n = sc.nextInt();
                if (n % 10 == 7 || n % 7 == 0)
                    System.out.println(n + " is a Buzz number");
                else
                    System.out.println(n + " is not a Buzz number");
                break;
            case 2:
                System.out.print("Enter two numbers: ");
                int a = sc.nextInt();
                int b = sc.nextInt();
                int dividend = Math.max(a, b);
                int divisor = Math.min(a, b);
                int r = dividend % divisor;
                while (r != 0)
                {
                    dividend = divisor;
                    divisor = r;
                    r = dividend % divisor;
                }
                System.out.println("GCD of " + a + " and " + b + " = " + divisor);
                break;
            default:
                System.out.println("Wrong choice");
        }
    }
}

/* Variable description
ch - menu choice
n - number checked for Buzz
a, b - numbers for GCD
dividend, divisor, r - values in the continued division
*/

