import java.util.*;

class ShowRoom
{
    String name;
    long mobno;
    double cost, dis, amount;

    ShowRoom()
    {
        name = "";
        mobno = 0;
        cost = 0.0;
        dis = 0.0;
        amount = 0.0;
    }

    void input()
    {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter customer name: ");
        name = sc.nextLine();
        System.out.print("Enter mobile number: ");
        mobno = sc.nextLong();
        System.out.print("Enter cost: ");
        cost = sc.nextDouble();
    }

    void calculate()
    {
        if (cost <= 10000)
            dis = cost * 5 / 100;
        else if (cost <= 20000)
            dis = cost * 10 / 100;
        else if (cost <= 35000)
            dis = cost * 15 / 100;
        else
            dis = cost * 20 / 100;
        amount = cost - dis;
    }

    void display()
    {
        System.out.println("Customer name : " + name);
        System.out.println("Mobile number : " + mobno);
        System.out.println("Amount to be paid : " + amount);
    }

    public static void main(String args[])
    {
        ShowRoom ob = new ShowRoom();
        ob.input();
        ob.calculate();
        ob.display();
    }
}

