import java.util.*;

class Smith
{
    static int sumDigits(int n)
    {
        int s = 0;
        while (n > 0)
        {
            s = s + n % 10;
            n = n / 10;
        }
        return s;
    }

    static boolean isPrime(int n)
    {
        if (n < 2)
            return false;
        for (int i = 2; i <= n / 2; i++)
        {
            if (n % i == 0)
                return false;
        }
        return true;
    }

    public static void main(String args[])
    {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter a number: ");
        int num = sc.nextInt();
        if (num < 4 || isPrime(num))
        {
            System.out.println(num + " is not a Smith number (not composite)");
            return;
        }
        int n = num, sf = 0;
        for (int i = 2; n > 1; i++)
        {
            while (n % i == 0)
            {
                sf = sf + sumDigits(i);
                n = n / i;
            }
        }
        if (sumDigits(num) == sf)
            System.out.println(num + " is a Smith number");
        else
            System.out.println(num + " is not a Smith number");
    }
}

/* Variable description
num - number entered
n - copy reduced during factorisation
i - trial factor
sf - sum of digits of prime factors
s - sum of digits (in sumDigits)
*/

Check: 666 = 2 × 3 × 3 × 37; digit sum 18; factor digit sum 2 + 3 + 3 + 3 + 7 = 18, so 666 is a Smith number.

